local open = io.open
local popen = io.popen
local string, format = string, string.format
local register = register

local sys_bootp_ = {
    objectType = {
        name = "sys.bootp.",
        access = "readOnly",
        minEntries = 1,
        maxEntries = 1,
        parameters = {
            enable = {
                access = "readWrite",
                type = "boolean"
            },
        },
    }
}

local function getall(mapping, key)
  local returnvars = {}
  returnvars["enable"] = "0"
  return returnvars
end


local function get(mapping, paramName, key)
   local value = getall(mapping, key)
   return value[paramName]
end


local set = {
  enable = function(mapping, param, value)
    local enableboop = popen("bootp")
    return true
  end
}


sys_bootp_.get = get
sys_bootp_.set = set
register(sys_bootp_)